
// Techlystb fallback JS
(function () {
  console.warn("Fallback JS activated.");

  // ডমে একটি সতর্ক বার্তা দেখানো
  const fallbackBox = document.createElement("div");
  fallbackBox.innerHTML = "⚠️ মূল ফিচার লোড হয়নি, fallback চালু হয়েছে";
  fallbackBox.style = `
    position:fixed;
    bottom:10px;
    left:10px;
    background:#ffdddd;
    color:#000;
    padding:10px 15px;
    border:1px solid #f00;
    font-family:sans-serif;
    font-size:14px;
    z-index:9999;
    box-shadow:0 0 10px rgba(0,0,0,0.2);
  `;
  document.body.appendChild(fallbackBox);
})();

